let dictSet = null
function getDict() {
  if (!dictSet) {
    dictSet = new Set()
    for (let i = 0; i < PACKED.length; i += 5) dictSet.add(PACKED.slice(i, i + 5))
  }
  return dictSet
}

/** True if the word (any case) is a valid 5-letter guess. */
export function isValidWord(word) {
  return typeof word === 'string' && word.length === 5 && getDict().has(word.toLowerCase())
}
